-- Sealed: pack arts, loose vs blister packs, blister boxes, more starter decks, sealed collections (2026-11-27).
-- products.parent_id: an art (or one deck) under its set-level entry. The set-level entry keeps every sale,
--   including titles that don't say which art (David: set-level price for those); an art entry gets the sales that
--   name it. products.art: the art's short name ("Silver Naruto").
-- New kinds: blister_pack (one booster pack in a retail blister; booster_pack = loose pack) and blister_box.
-- Every row added here is a PLACEHOLDER from web research (confirmed = false) for David to OK or fix in the Hub.
-- Two arts per set (David). Sets whose art names weren't found yet get them when David names them.
-- collection_sealed: members' sealed haves/wants (the collecting side), private like collection_items.

alter table products add column if not exists parent_id text references products(id) on delete set null,
  add column if not exists art text;

on conflict (id) do nothing;

-- the old single Path to Hokage entry becomes the set-level parent of the two starter decks
update products set name = 'The Path to Hokage starter deck' where id = '1-starter' and name = 'The Path to Hokage starter decks';

create table if not exists public.collection_sealed (
  user_id uuid not null references auth.users(id) on delete cascade,
  product_id text not null references products(id) on delete cascade,
  kind text not null check (kind in ('have','want')),
  qty integer not null default 1 check (qty >= 0 and qty <= 999),
  edition text not null default '',
  updated_at timestamptz not null default now(),
  primary key (user_id, product_id, kind, edition)
);
alter table public.collection_sealed enable row level security;
create policy "own sealed read" on public.collection_sealed for select using (user_id = auth.uid());
create policy "own sealed insert" on public.collection_sealed for insert with check (user_id = auth.uid());
create policy "own sealed update" on public.collection_sealed for update using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own sealed delete" on public.collection_sealed for delete using (user_id = auth.uid());
